SELECT SUM(pv) AS total_pv, SUM(uv) AS total_uv, SUM(uip) AS total_uip FROM t_link_access_stats WHERE full_short_url IN
#{url}
AND date BETWEEN #{start} AND #{end} AND del_flag = 0

SELECT date, SUM(pv) AS pv, SUM(uv) AS uv, SUM(uip) AS uip FROM t_link_access_stats WHERE full_short_url IN
#{url}
AND date BETWEEN #{start} AND #{end} AND del_flag = 0 GROUP BY date ORDER BY date ASC

SELECT hour, SUM(pv) AS pv FROM t_link_access_stats WHERE full_short_url IN
#{url}
AND date BETWEEN #{start} AND #{end} AND del_flag = 0 GROUP BY hour ORDER BY hour ASC

SELECT weekday, SUM(pv) AS pv FROM t_link_access_stats WHERE full_short_url IN
#{url}
AND date BETWEEN #{start} AND #{end} AND del_flag = 0 GROUP BY weekday ORDER BY weekday ASC

SELECT full_short_url, SUM(pv) AS total_pv, SUM(uv) AS total_uv, SUM(uip) AS total_uip, SUM(CASE WHEN date = CURDATE() THEN pv ELSE 0 END) AS today_pv, SUM(CASE WHEN date = CURDATE() THEN uv ELSE 0 END) AS today_uv, SUM(CASE WHEN date = CURDATE() THEN uip ELSE 0 END) AS today_uip FROM t_link_access_stats WHERE full_short_url IN
#{url}
AND del_flag = 0 GROUP BY full_short_url
